507: static amqp_bytes_t sasl_method_name(amqp_sasl_method_enum method) {
508:   amqp_bytes_t res;
509: 
510:   switch (method) {
511:     case AMQP_SASL_METHOD_PLAIN:
512:       res = amqp_literal_bytes("PLAIN");
513:       break;
514:     case AMQP_SASL_METHOD_EXTERNAL:
515:       res = amqp_literal_bytes("EXTERNAL");
516:       break;
517: 
518:     default:
519:       amqp_abort("Invalid SASL method: %d", (int)method);
520:   }
521: 
522:   return res;
523: }
524: 
525: static int bytes_equal(amqp_bytes_t l, amqp_bytes_t r) {
526:   if (l.len == r.len) {
527:     if (l.bytes && r.bytes) {
528:       if (0 == memcmp(l.bytes, r.bytes, l.len)) {
529:         return 1;
530:       }
531:     }
532:   }
533:   return 0;
534: }
535: 
536: int sasl_mechanism_in_list(amqp_bytes_t mechanisms,
537:                            amqp_sasl_method_enum method) {
538:   amqp_bytes_t mechanism;
539:   amqp_bytes_t supported_mechanism;
540:   uint8_t *start;
541:   uint8_t *end;
542:   uint8_t *current;
543: 
544:   assert(NULL != mechanisms.bytes);
545: 
546:   mechanism = sasl_method_name(method);
547: 
548:   start = (uint8_t *)mechanisms.bytes;
549:   current = start;
550:   end = start + mechanisms.len;
551: 
552:   for (; current != end; start = current + 1) {
553:     /* HACK: SASL states that we should be parsing this string as a UTF-8
554:      * string, which we're plainly not doing here. At this point its not worth
555:      * dragging an entire UTF-8 parser for this one case, and this should work
556:      * most of the time */
557:     current = memchr(start, ' ', end - start);
558:     if (NULL == current) {
559:       current = end;
560:     }
561:     supported_mechanism.bytes = start;
562:     supported_mechanism.len = current - start;
563:     if (bytes_equal(mechanism, supported_mechanism)) {
564:       return 1;
565:     }
566:   }
567: 
568:   return 0;
569: }
570: 
571: static amqp_bytes_t sasl_response(amqp_pool_t *pool,
572:                                   amqp_sasl_method_enum method, va_list args) {
573:   amqp_bytes_t response;
574: 
575:   switch (method) {
576:     case AMQP_SASL_METHOD_PLAIN: {
577:       char *username = va_arg(args, char *);
578:       size_t username_len = strlen(username);
579:       char *password = va_arg(args, char *);
580:       size_t password_len = strlen(password);
581:       char *response_buf;
582: 
583:       amqp_pool_alloc_bytes(pool, strlen(username) + strlen(password) + 2,
584:                             &response);
585:       if (response.bytes == NULL)
586:       /* We never request a zero-length block, because of the +2
587:          above, so a NULL here really is ENOMEM. */
588:       {
589:         return response;
590:       }
591: 
592:       response_buf = response.bytes;
593:       response_buf[0] = 0;
594:       memcpy(response_buf + 1, username, username_len);
595:       response_buf[username_len + 1] = 0;
596:       memcpy(response_buf + username_len + 2, password, password_len);
597:       break;
598:     }
599:     case AMQP_SASL_METHOD_EXTERNAL: {
600:       char *identity = va_arg(args, char *);
601:       size_t identity_len = strlen(identity);
602: 
603:       amqp_pool_alloc_bytes(pool, identity_len, &response);
604:       if (response.bytes == NULL) {
605:         return response;
606:       }
607: 
608:       memcpy(response.bytes, identity, identity_len);
609:       break;
610:     }
611:     default:
612:       amqp_abort("Invalid SASL method: %d", (int)method);
613:   }
614: 
615:   return response;
616: }
