805: static amqp_link_t *amqp_create_link_for_frame(amqp_connection_state_t state,
806:                                                amqp_frame_t *frame) {
807:   amqp_link_t *link;
808:   amqp_frame_t *frame_copy;
809: 
810:   amqp_pool_t *channel_pool =
811:       amqp_get_or_create_channel_pool(state, frame->channel);
812: 
813:   if (NULL == channel_pool) {
814:     return NULL;
815:   }
816: 
817:   link = amqp_pool_alloc(channel_pool, sizeof(amqp_link_t));
818:   frame_copy = amqp_pool_alloc(channel_pool, sizeof(amqp_frame_t));
819: 
820:   if (NULL == link || NULL == frame_copy) {
821:     return NULL;
822:   }
823: 
824:   *frame_copy = *frame;
825:   link->data = frame_copy;
826: 
827:   return link;
828: }
