911: int amqp_simple_wait_frame_noblock(amqp_connection_state_t state,
912:                                    amqp_frame_t *decoded_frame,
913:                                    const struct timeval *timeout) {
914:   amqp_time_t deadline;
915: 
916:   int res = amqp_time_from_now(&deadline, timeout);
917:   if (AMQP_STATUS_OK != res) {
918:     return res;
919:   }
920: 
921:   if (state->first_queued_frame != NULL) {
922:     amqp_frame_t *f = (amqp_frame_t *)state->first_queued_frame->data;
923:     state->first_queued_frame = state->first_queued_frame->next;
924:     if (state->first_queued_frame == NULL) {
925:       state->last_queued_frame = NULL;
926:     }
927:     *decoded_frame = *f;
928:     return AMQP_STATUS_OK;
929:   } else {
930:     return wait_frame_inner(state, decoded_frame, deadline);
931:   }
932: }
