1000: static int amqp_id_in_reply_list(amqp_method_number_t expected,
1001:                                  amqp_method_number_t *list) {
1002:   while (*list != 0) {
1003:     if (*list == expected) {
1004:       return 1;
1005:     }
1006:     list++;
1007:   }
1008:   return 0;
1009: }
