1011: static amqp_rpc_reply_t simple_rpc_inner(
1012:     amqp_connection_state_t state, amqp_channel_t channel,
1013:     amqp_method_number_t request_id, amqp_method_number_t *expected_reply_ids,
1014:     void *decoded_request_method, amqp_time_t deadline) {
1015:   int status;
1016:   amqp_rpc_reply_t result;
1017: 
1018:   memset(&result, 0, sizeof(result));
1019: 
1020:   status = amqp_send_method(state, channel, request_id, decoded_request_method);
1021:   if (status < 0) {
1022:     return amqp_rpc_reply_error(status);
1023:   }
1024: 
1025:   {
1026:     amqp_frame_t frame;
1027: 
1028:   retry:
1029:     status = wait_frame_inner(state, &frame, deadline);
1030:     if (status != AMQP_STATUS_OK) {
1031:       if (status == AMQP_STATUS_TIMEOUT) {
1032:         amqp_socket_close(state->socket, AMQP_SC_FORCE);
1033:       }
1034:       return amqp_rpc_reply_error(status);
1035:     }
1036: 
1037:     /*
1038:      * We store the frame for later processing unless it's something
1039:      * that directly affects us here, namely a method frame that is
1040:      * either
1041:      *  - on the channel we want, and of the expected type, or
1042:      *  - on the channel we want, and a channel.close frame, or
1043:      *  - on channel zero, and a connection.close frame.
1044:      */
1045:     if (!((frame.frame_type == AMQP_FRAME_METHOD) &&
1046:           (((frame.channel == channel) &&
1047:             (amqp_id_in_reply_list(frame.payload.method.id,
1048:                                    expected_reply_ids) ||
1049:              (frame.payload.method.id == AMQP_CHANNEL_CLOSE_METHOD))) ||
1050:            ((frame.channel == 0) &&
1051:             (frame.payload.method.id == AMQP_CONNECTION_CLOSE_METHOD))))) {
1052:       amqp_pool_t *channel_pool;
1053:       amqp_frame_t *frame_copy;
1054:       amqp_link_t *link;
1055: 
1056:       channel_pool = amqp_get_or_create_channel_pool(state, frame.channel);
1057:       if (NULL == channel_pool) {
1058:         return amqp_rpc_reply_error(AMQP_STATUS_NO_MEMORY);
1059:       }
1060: 
1061:       frame_copy = amqp_pool_alloc(channel_pool, sizeof(amqp_frame_t));
1062:       link = amqp_pool_alloc(channel_pool, sizeof(amqp_link_t));
1063: 
1064:       if (frame_copy == NULL || link == NULL) {
1065:         return amqp_rpc_reply_error(AMQP_STATUS_NO_MEMORY);
1066:       }
1067: 
1068:       *frame_copy = frame;
1069: 
1070:       link->next = NULL;
1071:       link->data = frame_copy;
1072: 
1073:       if (state->last_queued_frame == NULL) {
1074:         state->first_queued_frame = link;
1075:       } else {
1076:         state->last_queued_frame->next = link;
1077:       }
1078:       state->last_queued_frame = link;
1079: 
1080:       goto retry;
1081:     }
1082: 
1083:     result.reply_type =
1084:         (amqp_id_in_reply_list(frame.payload.method.id, expected_reply_ids))
1085:             ? AMQP_RESPONSE_NORMAL
1086:             : AMQP_RESPONSE_SERVER_EXCEPTION;
1087: 
1088:     result.reply = frame.payload.method;
1089:     return result;
1090:   }
1091: }
1092: 
1093: amqp_rpc_reply_t amqp_simple_rpc(amqp_connection_state_t state,
1094:                                  amqp_channel_t channel,
1095:                                  amqp_method_number_t request_id,
1096:                                  amqp_method_number_t *expected_reply_ids,
1097:                                  void *decoded_request_method) {
1098:   amqp_time_t deadline;
1099:   int res;
1100: 
1101:   res = amqp_time_from_now(&deadline, state->rpc_timeout);
1102:   if (res != AMQP_STATUS_OK) {
1103:     return amqp_rpc_reply_error(res);
1104:   }
1105: 
1106:   return simple_rpc_inner(state, channel, request_id, expected_reply_ids,
1107:                           decoded_request_method, deadline);
1108: }
1109: 
1110: void *amqp_simple_rpc_decoded(amqp_connection_state_t state,
1111:                               amqp_channel_t channel,
1112:                               amqp_method_number_t request_id,
1113:                               amqp_method_number_t reply_id,
1114:                               void *decoded_request_method) {
1115:   amqp_time_t deadline;
1116:   int res;
